package com.nexus.enchants.config;

import com.nexus.enchants.util.EnchantmentWeight;
import java.util.Map;
import java.util.Objects;
import java.util.Set;

/**
 * Immutable librarian rarity configuration.
 *
 * <p>An enchantment that is not listed is never generated by the plugin. That
 * is intentional: the table is the complete pool, so an administrator removing
 * a line removes the enchantment.</p>
 */
public final class VillagerRarityConfig {

    private final boolean enabled;
    private final SelectionMode selectionMode;
    private final Map<String, EnchantmentWeight> weights;
    private final Map<String, Map<Integer, Integer>> levelWeights;
    private final boolean treasureEnabled;
    private final Set<String> disabledEnchantments;

    /**
     * Creates the configuration.
     *
     * @param enabled             whether the system is enabled
     * @param selectionMode       selection strategy
     * @param weights             canonical key to weight
     * @param levelWeights        optional canonical key to level to weight overrides
     * @param treasureEnabled     whether treasure enchantments may be generated
     * @param disabledEnchantments canonical keys that are never generated
     */
    public VillagerRarityConfig(
            boolean enabled,
            SelectionMode selectionMode,
            Map<String, EnchantmentWeight> weights,
            Map<String, Map<Integer, Integer>> levelWeights,
            boolean treasureEnabled,
            Set<String> disabledEnchantments) {
        this.enabled = enabled;
        this.selectionMode = Objects.requireNonNull(selectionMode, "selectionMode");
        this.weights = Map.copyOf(weights);
        this.levelWeights = Map.copyOf(levelWeights);
        this.treasureEnabled = treasureEnabled;
        this.disabledEnchantments = Set.copyOf(disabledEnchantments);
    }

    /**
     * Returns a disabled configuration that leaves vanilla generation alone.
     *
     * @return a disabled configuration
     */
    public static VillagerRarityConfig disabled() {
        return new VillagerRarityConfig(false, SelectionMode.DISABLED, Map.of(), Map.of(), true, Set.of());
    }

    /**
     * Returns whether the weighted table is active.
     *
     * @return {@code true} when enabled and in weighted mode
     */
    public boolean active() {
        return enabled && selectionMode == SelectionMode.WEIGHTED;
    }

    /**
     * Returns the configured weight of an enchantment.
     *
     * @param enchantmentKey canonical enchantment key
     * @return the weight, disabled by default when unlisted
     */
    public EnchantmentWeight weightOf(String enchantmentKey) {
        EnchantmentWeight weight = weights.get(enchantmentKey);
        if (weight == null || disabledEnchantments.contains(enchantmentKey)) {
            return new EnchantmentWeight(false, 0);
        }
        return weight;
    }

    /**
     * Returns the optional per-level rarity override.
     *
     * @param enchantmentKey canonical enchantment key
     * @return level to weight map, empty when no override exists
     */
    public Map<Integer, Integer> levelWeightsFor(String enchantmentKey) {
        return levelWeights.getOrDefault(enchantmentKey, Map.of());
    }

    /**
     * Returns whether any enchantment can be generated.
     *
     * @return {@code true} when at least one weight is selectable
     */
    public boolean hasSelectableEnchantments() {
        for (EnchantmentWeight weight : weights.values()) {
            if (weight.selectable()) {
                return true;
            }
        }
        return false;
    }

    /**
     * Returns whether the system is enabled at all.
     *
     * @return the configured enabled flag
     */
    public boolean enabled() {
        return enabled;
    }

    /**
     * Returns a short label used in the startup log.
     *
     * @return {@code on (weighted)}, {@code off} or {@code on (disabled mode)}
     */
    public String activationLabel() {
        if (!enabled) {
            return "off";
        }
        return selectionMode == SelectionMode.WEIGHTED ? "on (weighted)" : "on (disabled mode)";
    }

    /**
     * Returns the configured selection mode.
     *
     * @return the selection mode
     */
    public SelectionMode selectionMode() {
        return selectionMode;
    }

    /**
     * Returns whether treasure enchantments may be generated.
     *
     * @return {@code true} when treasure enchantments are allowed
     */
    public boolean treasureEnabled() {
        return treasureEnabled;
    }

    /**
     * Returns the explicit disable list.
     *
     * @return immutable set of canonical keys
     */
    public Set<String> disabledEnchantments() {
        return disabledEnchantments;
    }

    /**
     * Returns every configured weight.
     *
     * @return immutable canonical key to weight map
     */
    public Map<String, EnchantmentWeight> weights() {
        return weights;
    }
}
